//! Stage 2b: the generic normal form and admission of an ideal.
use crate::geometry::{
    self, hermitian, inverse_odd, secret_norm_bits, DENOMINATOR_SQUARE_BITS, GUARD_BITS,
    ORDER_DENOMINATOR_BITS,
};
use crate::{field_prime, Gaussian, IdealSet, Vector};
use prism_int::{Int, SecretBit, SecretInt as Scalar};
use std::marker::PhantomData;

/// Column-HNF of the left ideal of norm `N` generated by the root `x + yi + j`.
///
/// The shape is fixed. The first column is the pivot `(2N, 0, 0, 0)` and the
/// third is `(x, y, 1, 0)`. [`Self::generators`] is that pair. An HNF of
/// another shape has no conversion here: its spanning pair is the caller's.
#[derive(Clone)]
pub struct GenericHnf<const W: usize> {
    columns: [Vector<W>; 4],
}

impl<const W: usize> GenericHnf<W> {
    const PIVOT_COLUMN: usize = 0;
    const ROOT_COLUMN: usize = 2;

    /// Columns for norm `norm` and Gaussian root `root = (x, y)`.
    ///
    /// The fourth column is `i·(x + yi + j)` with its real coordinate lifted
    /// by `2N`. For an admissible root, `y` is odd and `0 < y < 2N`, so
    /// `2N − y` is the canonical residue. Admission checks the candidate
    /// columns and the generic reducer checks the root parity.
    pub fn from_norm_and_root(norm: &Scalar<W>, root: &Gaussian<W>) -> Self {
        let pivot = norm.shl(ORDER_DENOMINATOR_BITS);
        let zero = Scalar::zero();
        let [x, y] = root;
        Self {
            columns: [
                [pivot.clone(), zero.clone(), zero.clone(), zero.clone()],
                [zero.clone(), pivot.clone(), zero.clone(), zero.clone()],
                [x.clone(), y.clone(), Scalar::one(), zero.clone()],
                [pivot.sub(y), x.clone(), zero, Scalar::one()],
            ],
        }
    }

    /// The four columns, pivot column first.
    pub fn columns(&self) -> &[Vector<W>; 4] {
        &self.columns
    }

    /// The pivot `2N`.
    pub fn pivot(&self) -> &Scalar<W> {
        &self.columns[Self::PIVOT_COLUMN][0]
    }

    /// Generators the generic reducer consumes: the `2N` pivot and the root column.
    pub fn generators(&self) -> (Vector<W>, Vector<W>) {
        (
            self.columns[Self::PIVOT_COLUMN].clone(),
            self.columns[Self::ROOT_COLUMN].clone(),
        )
    }
}

/// An integral left ideal whose pre-reduced basis passed the factor-256 guard.
/// Integer fields are supplied by generation or by a key-format decoder.
pub struct GuardedIdeal<S: IdealSet<W, D>, const W: usize, const D: usize> {
    set: PhantomData<S>,
    pub(crate) p: Scalar<D>,
    pub(crate) norm: Scalar<W>,
    pub(crate) u: Vector<W>,
    pub(crate) v: Vector<W>,
}

fn product<const W: usize>([a, b]: [&Scalar<W>; 2], [c, d]: [&Scalar<W>; 2]) -> Gaussian<W> {
    [a.mul(c).sub(&b.mul(d)), a.mul(d).add(&b.mul(c))]
}

fn difference<const W: usize>(a: Gaussian<W>, b: Gaussian<W>) -> Gaussian<W> {
    [a[0].sub(&b[0]), a[1].sub(&b[1])]
}

fn cross<const W: usize>(u: &Vector<W>, v: &Vector<W>) -> Gaussian<W> {
    let [a, b, c, d] = u;
    let [e, f, g, h] = v;
    difference(product([a, b], [g, h]), product([e, f], [c, d]))
}

fn abs_squared<const W: usize>(a: &Gaussian<W>) -> Scalar<W> {
    a[0].mul(&a[0]).add(&a[1].mul(&a[1]))
}

pub(crate) fn rotate<const W: usize>(v: &Vector<W>) -> Vector<W> {
    [v[1].neg(), v[0].clone(), v[3].neg(), v[2].clone()]
}

// Membership via Cramer's rule over Z[i]. Both determinants divided by
// det(u,v) must be Gaussian integers. Its squared magnitude is 4 N^2.
struct Span<const D: usize> {
    u: Vector<D>,
    v: Vector<D>,
    conjugate: Gaussian<D>,
    n2: Scalar<D>,
    inverse: Scalar<D>,
}

impl<const D: usize> Span<D> {
    fn contains(&self, w: &Vector<D>) -> SecretBit {
        let mut ok = self.n2.is_odd();
        for numerator in [cross(w, &self.v), cross(&self.u, w)] {
            for z in product(numerator.each_ref(), self.conjugate.each_ref()) {
                let mag = z.abs().shr(DENOMINATOR_SQUARE_BITS);
                let q = mag.mul_low(&self.inverse);
                ok = ok
                    .and(&z.low_bits_zero(DENOMINATOR_SQUARE_BITS))
                    .and(&q.mul(&self.n2).ct_eq(&mag));
            }
        }
        ok
    }
}

impl<S: IdealSet<W, D>, const W: usize, const D: usize> GuardedIdeal<S, W, D> {
    /// Shared by generation and import after the key's integer fields are decoded.
    /// HNF columns are in raw numerator coordinates, with positive pivots.
    pub fn admit(
        norm: Scalar<W>,
        hnf: &[Vector<W>; 4],
        u: Vector<W>,
        v: Vector<W>,
    ) -> Option<Self> {
        let prime = field_prime::<S, W, D>()?;
        let limit =
            Scalar::from_public(&Int::one().shl(secret_norm_bits(prime.bit_length())).ok()?);
        let p = Scalar::<W>::from_public(&prime).resize::<D>();
        let n = norm.resize::<D>();
        let n2 = n.mul(&n);
        let u_wide = u.each_ref().map(Scalar::resize);
        let v_wide = v.each_ref().map(Scalar::resize);
        let det = cross(&u_wide, &v_wide);
        let index = n2.shl(DENOMINATOR_SQUARE_BITS);
        let mut ok = norm
            .is_odd()
            .and(&norm.is_negative().not())
            .and(&norm.ct_lt(&limit))
            .and(&abs_squared(&det).ct_eq(&index));
        let span = Span {
            u: u_wide,
            v: v_wide,
            conjugate: [det[0].clone(), det[1].neg()],
            inverse: inverse_odd(&n2),
            n2,
        };
        let mut hnf_index = Scalar::<D>::one();
        for (j, col) in hnf.iter().enumerate() {
            ok = ok.and(&Scalar::zero().ct_lt(&col[j]));
            hnf_index = hnf_index.mul(&col[j].resize());
            for (i, x) in col.iter().enumerate() {
                if i < j {
                    ok = ok.and(&x.is_negative().not()).and(&x.ct_lt(&hnf[i][i]));
                }
                if i > j {
                    ok = ok.and(&x.ct_eq(&Scalar::zero()));
                }
            }
            ok = ok.and(&span.contains(&col.each_ref().map(Scalar::resize)));
        }
        ok = ok.and(&hnf_index.ct_eq(&index));
        // O0 = <1,i,(i+j)/2,(1+k)/2>; (1+k)/2 = 1 + i(i+j)/2.
        // i-stability is automatic for a Gaussian pair. Test the remaining
        // generator on *all four* integer columns, including iU and iV.
        let p_plus_one_over_two = p.shr(ORDER_DENOMINATOR_BITS).add(&Scalar::one());
        for w in [&span.u, &span.v] {
            for col in [w, &rotate(w)] {
                let (image, integral) = geometry::left_half_i_plus_j(col, &p_plus_one_over_two);
                ok = ok.and(&integral).and(&span.contains(&image));
            }
        }
        let weight = |w: &Vector<D>| hermitian(w, w, &p).0;
        let a = weight(&span.u);
        let c = weight(&span.v);
        // N4(v) ≤ 2^{DENOMINATOR_SQUARE_BITS + GUARD_BITS} · N · √p,
        // because N4 = 2^{DENOMINATOR_SQUARE_BITS} · nrd.
        let cap = n.shl(DENOMINATOR_SQUARE_BITS + GUARD_BITS);
        ok = ok
            .and(&Scalar::zero().ct_lt(&a))
            .and(&c.ct_lt(&a).not())
            .and(&p.mul(&cap.mul(&cap)).ct_lt(&c.mul(&c)).not());
        ok.declassify().unwrap_or(false).then_some(Self {
            norm,
            u,
            v,
            p,
            set: PhantomData,
        })
    }
}
